import { mkdir, mkdtemp, rm } from 'node:fs/promises';
import { join, relative } from 'node:path';

import { generateApi } from './generate.ts';
import { apiArtifacts, REPOSITORY_ROOT } from './paths.ts';

/** Compare regenerated bytes without overwriting a contributor's edited artifacts. */
export async function checkApiDrift(committed = apiArtifacts()) {
  const original = await Promise.all([
    Bun.file(committed.contract).text(),
    Bun.file(committed.types).text(),
  ]);
  await mkdir(join(REPOSITORY_ROOT, '.turbo'), { recursive: true });
  const directory = await mkdtemp(join(REPOSITORY_ROOT, '.turbo/api-check-'));
  try {
    const fresh = {
      contract: join(directory, 'openapi.json'),
      types: join(directory, 'generated.ts'),
    };
    await generateApi(fresh);
    const outputs = await Promise.all([
      Bun.file(fresh.contract).text(),
      Bun.file(fresh.types).text(),
    ]);
    const changed = [committed.contract, committed.types].filter(
      (_path, index) => original[index] !== outputs[index],
    );
    if (changed.length)
      throw new Error(
        `Generated API artifacts drifted: ${changed.map((path) => relative(REPOSITORY_ROOT, path)).join(', ')}. Run bun run api:generate.`,
      );
  } finally {
    await rm(directory, { recursive: true, force: true });
  }
}
if (import.meta.main) await checkApiDrift();
